from __future__ import annotations
from cadgen import step
from lib.steve_compat import to_build123d


def make():
    import math
    import cadquery as cq
    from lib.steve_compat import Model
    SIDE = 1
    split_z = -12.3857
    axis_x = -42.899
    axis_z = 3.975
    shoulder_r = 21.99
    shoulder_y0 = 44.145
    shoulder_y1 = 90.315
    bed_r = 22.13
    bed_y0 = 45.78
    bed_y1 = 88.68
    plate_x0 = -69.899
    plate_x1 = 3.001
    plate_round_r = 6.75
    tab_x0_a = -65.5
    tab_x0_b = -15.2
    tab_dx = 4.0
    tab_y0 = 60.43
    tab_y1 = 74.03
    tab_h = 8.2
    draft_lo = ((40.339, -12.386), (40.722, -9.011))
    draft_hi = ((94.455, -12.386), (94.032, -9.011))
    
    def _p3(axis, lvl, u, v):
        return cq.Vector(*((lvl, u, v) if axis == 0 else (u, lvl, v) if axis == 1 else (u, v, lvl)))
    
    def _edges(ring, at):
        start, segs = ring
        cur = at(*start)
        edges = []
        for s in segs:
            nxt = at(*s[-1])
            if s[0] == 'A' and (at(*s[1]) - cur).cross(nxt - cur).Length > 0.0001:
                edges.append(cq.Edge.makeThreePointArc(cur, at(*s[1]), nxt))
            elif (nxt - cur).Length > 1e-06:
                edges.append(cq.Edge.makeLine(cur, nxt))
            cur = nxt
        return cq.Wire.assembleEdges(edges)
    
    def _face(axis, lvl, outer, holes=()):
        f = cq.Face.makeFromWires(_edges(outer, lambda u, v: _p3(axis, lvl, u, v)), [_edges(h, lambda u, v: _p3(axis, lvl, u, v)) for h in holes])
        return f if f.isValid() else f.fix()
    
    def slab_stack(axis, slabs):
        """Stacked extrusions along one world axis: [[lo, hi, [[outer_ring, [hole_rings]], ...]], ...].
        A ring is [start, segments]; a segment is ["L", end] or ["A", through, end]."""
        out = None
        for lo, hi, faces in slabs:
            d = [0, 0, 0]
            d[axis] = hi - lo
            for outer, holes in faces:
                s = cq.Solid.extrudeLinear(_face(axis, lo, outer, holes), cq.Vector(*d))
                out = s if out is None else out.fuse(s)
        return out.clean()
    
    def side(shape):
        return shape.mirror('XZ') if SIDE < 0 else shape
    
    def cradle_cut():
        shoulder = cq.Solid.makeCylinder(shoulder_r, shoulder_y1 - shoulder_y0, cq.Vector(axis_x, shoulder_y0, axis_z), cq.Vector(0, 1, 0))
        bed = cq.Solid.makeCylinder(bed_r, bed_y1 - bed_y0, cq.Vector(axis_x, bed_y0, axis_z), cq.Vector(0, 1, 0))
        return shoulder.fuse(bed)
    
    def top_envelope():
        c = math.sqrt(0.5) * plate_round_r
        xa, xb = (plate_x0 + plate_round_r, plate_x1 - plate_round_r)
        return cq.Workplane('XZ').moveTo(plate_x0, split_z - 1).lineTo(plate_x1, split_z - 1).lineTo(plate_x1, split_z).threePointArc((xb + c, split_z + c), (xb, split_z + plate_round_r)).lineTo(xb, split_z + 20).lineTo(xa, split_z + 20).lineTo(xa, split_z + plate_round_r).threePointArc((xa - c, split_z + c), (plate_x0, split_z)).close().extrude(-200, both=True).val()
    
    def tab_boxes():
        return cq.Solid.makeBox(tab_dx, tab_y1 - tab_y0, tab_h + 1, cq.Vector(tab_x0_a, tab_y0, split_z - 1)).fuse(cq.Solid.makeBox(tab_dx, tab_y1 - tab_y0, tab_h + 1, cq.Vector(tab_x0_b, tab_y0, split_z - 1)))
    
    def upper_body():
        return slab_stack(2, TOP_SLABS).intersect(top_envelope())
    
    def side_drafts():
        out = None
        for (y0, z0), (y1, z1), k in ((*draft_lo, -1), (*draft_hi, 1)):
            w = cq.Workplane('YZ').polyline([(y0, z0), (y1, z1), (y1 + 5 * k, z1), (y0 + 5 * k, z0)]).close().extrude(100, both=True).val()
            out = w if out is None else out.fuse(w)
        return out
    TOP_SLABS = [[-12.386, -9.686, [[[[-5.664, 94.419], [['A', [0.535, 91.344], [3.001, 84.666]], ['A', [2.975, 49.149], [2.884, 48.363]], ['A', [-0.019, 42.883], [-6.781, 40.341]], ['L', [-63.092, 40.367]], ['A', [-67.962, 42.781], [-69.899, 48.22]], ['L', [-69.879, 87.523]], ['A', [-67.527, 92.452], [-62.182, 94.452]], ['L', [-6.449, 94.452]], ['L', [-5.664, 94.419]]]], [[[-5.488, 78.705], [['L', [-6.669, 78.705]], ['L', [-6.669, 55.755]], ['L', [-5.488, 55.755]], ['L', [-5.488, 45.91]], ['A', [-3.776, 47.166], [-3.209, 48.988]], ['L', [-3.21, 85.514]], ['A', [-4.071, 87.661], [-5.488, 88.549]], ['L', [-5.488, 78.705]]]], [[-7.851, 88.695], [['L', [-10.044, 88.695]], ['L', [-10.044, 78.705]], ['L', [-7.851, 78.705]], ['L', [-7.851, 88.695]]]], [[-7.851, 55.755], [['L', [-10.044, 55.755]], ['L', [-10.044, 45.765]], ['L', [-7.851, 45.765]], ['L', [-7.851, 55.755]]]], [[-10.045, 75.33], [['L', [-14.634, 75.33]], ['L', [-14.634, 59.13]], ['L', [-10.044, 59.13]], ['L', [-10.045, 75.33]]]], [[-18.197, 67.23], [['A', [-19.277, 68.31], [-20.357, 67.23]], ['A', [-19.277, 66.15], [-18.197, 67.23]]]], [[-57.608, 88.83], [['L', [-61.479, 88.83]], ['L', [-61.479, 81.81]], ['L', [-57.608, 81.81]], ['L', [-57.608, 52.65]], ['L', [-61.479, 52.65]], ['L', [-61.479, 45.63]], ['L', [-57.608, 45.63]], ['L', [-57.607, 44.145]], ['L', [-28.19, 44.145]], ['L', [-28.191, 90.315]], ['L', [-57.608, 90.315]], ['L', [-57.608, 88.83]]]], [[-61.48, 75.33], [['L', [-66.069, 75.33]], ['L', [-66.069, 59.13]], ['L', [-61.479, 59.13]], ['L', [-61.48, 75.33]]]]]], [[[-11.712, 73.98], [['L', [-11.712, 60.48]], ['L', [-13.284, 60.48]], ['L', [-13.284, 73.98]], ['L', [-11.712, 73.98]]]], []], [[[-62.829, 73.98], [['L', [-62.829, 60.48]], ['L', [-64.402, 60.48]], ['L', [-64.402, 73.98]], ['L', [-62.829, 73.98]]]], []]]], [-9.686, -9.013, [[[[-69.324, 89.512], [['A', [-66.717, 92.769], [-62.474, 94.114]], ['L', [-5.98, 94.095]], ['A', [-0.598, 92.07], [2.426, 87.855]], ['L', [2.403, 46.829]], ['A', [-0.615, 42.677], [-6.449, 40.648]], ['L', [-63.114, 40.676]], ['A', [-66.786, 42.043], [-69.325, 45.243]], ['L', [-69.324, 89.512]]]], [[[-5.488, 78.705], [['L', [-6.669, 78.705]], ['L', [-6.669, 55.755]], ['L', [-5.488, 55.755]], ['L', [-5.488, 45.91]], ['A', [-3.754, 47.199], [-3.209, 48.988]], ['L', [-3.209, 85.472]], ['A', [-4.072, 87.662], [-5.488, 88.549]], ['L', [-5.488, 78.705]]]], [[-7.851, 88.695], [['L', [-10.044, 88.695]], ['L', [-10.044, 78.705]], ['L', [-7.851, 78.705]], ['L', [-7.851, 88.695]]]], [[-7.851, 55.755], [['L', [-10.044, 55.755]], ['L', [-10.03, 45.765]], ['L', [-7.851, 45.765]], ['L', [-7.851, 55.755]]]], [[-10.045, 75.33], [['L', [-14.634, 75.33]], ['L', [-14.634, 59.13]], ['L', [-10.044, 59.13]], ['L', [-10.045, 75.33]]]], [[-17.252, 67.23], [['A', [-19.277, 69.255], [-21.302, 67.23]], ['A', [-19.277, 65.205], [-17.252, 67.23]]]], [[-60.141, 81.81], [['L', [-60.141, 52.65]], ['L', [-61.479, 52.65]], ['L', [-61.479, 45.63]], ['L', [-60.141, 45.63]], ['L', [-60.12, 44.145]], ['L', [-31.042, 44.145]], ['A', [-31.042, 42.675], [-26.756, 42.675]], ['L', [-26.756, 44.145]], ['L', [-25.657, 44.145]], ['L', [-25.658, 90.315]], ['L', [-60.141, 90.315]], ['L', [-60.141, 88.83]], ['L', [-61.479, 88.815]], ['L', [-61.479, 81.81]], ['L', [-60.141, 81.81]]]], [[-61.48, 75.33], [['L', [-66.069, 75.33]], ['L', [-66.069, 59.13]], ['L', [-61.479, 59.13]], ['L', [-61.48, 75.33]]]]]], [[[-12.012, 73.98], [['L', [-12.012, 60.48]], ['L', [-13.284, 60.48]], ['L', [-13.284, 73.98]], ['L', [-12.012, 73.98]]]], []], [[[-62.829, 73.98], [['L', [-62.829, 60.48]], ['L', [-64.102, 60.48]], ['L', [-64.102, 73.98]], ['L', [-62.829, 73.98]]]], []]]], [-9.013, -6.986, [[[[-13.284, 59.13], [['L', [-10.044, 59.13]], ['L', [-10.045, 75.33]], ['L', [-13.284, 75.33]], ['L', [-13.284, 93.957]], ['L', [-5.664, 93.924]], ['A', [-1.147, 92.316], [1.699, 89.252]], ['L', [1.7, 45.489]], ['A', [-1.37, 42.282], [-6.449, 40.791]], ['L', [-13.284, 40.791]], ['L', [-13.284, 59.13]]]], []], [[[-12.152, 73.98], [['L', [-12.152, 60.48]], ['L', [-13.284, 60.48]], ['L', [-13.284, 73.98]], ['L', [-12.152, 73.98]]]], []], [[[-62.829, 93.948], [['L', [-62.829, 75.33]], ['L', [-66.069, 75.33]], ['L', [-66.069, 59.13]], ['L', [-62.829, 59.13]], ['L', [-62.829, 40.799]], ['A', [-65.835, 41.607], [-68.597, 44.041]], ['L', [-68.578, 90.734]], ['A', [-66.028, 93.044], [-62.829, 93.948]]]], []], [[[-62.829, 73.98], [['L', [-62.829, 60.48]], ['L', [-63.962, 60.48]], ['L', [-63.962, 73.98]], ['L', [-62.829, 73.98]]]], []]]], [-6.986, -5.636, [[[[-13.284, 75.33], [['L', [-13.284, 93.754]], ['L', [-5.664, 93.721]], ['A', [-2.023, 92.641], [0.015, 91.177]], ['L', [0.015, 43.549]], ['A', [-2.159, 42.014], [-6.449, 40.975]], ['L', [-13.284, 40.975]], ['L', [-13.284, 59.13]], ['L', [-10.044, 59.13]], ['L', [-10.045, 75.33]], ['L', [-13.284, 75.33]]]], []], [[[-12.332, 73.98], [['L', [-12.332, 60.48]], ['L', [-14.634, 60.48]], ['L', [-14.634, 73.98]], ['L', [-12.332, 73.98]]]], []], [[[-61.479, 73.98], [['L', [-61.479, 60.48]], ['L', [-63.782, 60.48]], ['L', [-63.782, 73.98]], ['L', [-61.479, 73.98]]]], []], [[[-62.829, 93.745], [['L', [-62.829, 75.33]], ['L', [-66.069, 75.33]], ['L', [-66.069, 59.13]], ['L', [-62.829, 59.13]], ['L', [-62.829, 40.983]], ['A', [-64.897, 41.384], [-66.91, 42.458]], ['L', [-66.886, 92.289]], ['A', [-64.899, 93.343], [-62.829, 93.745]]]], []]]], [-5.636, -4.286, [[[[-12.534, 73.98], [['L', [-12.534, 60.48]], ['L', [-14.162, 60.48]], ['L', [-14.162, 73.98]], ['L', [-12.534, 73.98]]]], []], [[[-61.952, 73.98], [['L', [-61.952, 60.48]], ['L', [-63.579, 60.48]], ['L', [-63.579, 73.98]], ['L', [-61.952, 73.98]]]], []]]]]
    model = Model()
    model.add('top_plate', side(upper_body().cut(tab_boxes())))
    model.add('cradle_bed', side(cradle_cut()), op='cut')
    model.add('side_drafts', side(side_drafts()), op='cut')
    model.material('pla', color='#f96c0a')
    result = model.result()
    return to_build123d(model, 'foot_left_native_b')


@step(out="../../STEP/parts/foot_left_native_b_seated.step")
def foot_left_native_b_seated():
    return make()


if __name__ == "__main__":
    foot_left_native_b_seated()
